        return ast.unparse(node)
    except Exception:
        return name_of(node)

def is_match(name, symbol):
    return (not symbol) or (symbol in name)

def main():
    try:
        raw = sys.stdin.read()
        params = json.loads(raw) if raw.strip() else {}
    except Exception:
        params = {}
    symbol = params.get('symbol', '')
    path_filter = params.get('path', '')
    include_refs = bool(params.get('include_references', False))
    try:
        max_results = int(params.get('max_results', 60))
    except Exception:
        max_results = 60
    root = '/testbed'
    definitions = []
    references = []
    files_searched = 0
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if not d.startswith('.') and d not in ('__pycache__', 'node_modules')]
        for filename in filenames:
            if not filename.endswith('.py'):
                continue
            path = os.path.join(dirpath, filename)
            rel = os.path.relpath(path, root)
            if path_filter and path_filter not in rel:
                continue
            files_searched += 1
            try:
                with open(path, 'r', encoding='utf-8', errors='replace') as f:
                    source = f.read()
            except Exception:
                continue
            if include_refs and symbol:
                lines = source.splitlines()
                for lineno, line in enumerate(lines, 1):
                    if symbol in line:
                        references.append({'path': rel, 'line': lineno, 'text': line.strip()[:220]})
            try:
                tree = ast.parse(source)
            except SyntaxError:
                continue
            for node in ast.walk(tree):
                if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                    if is_match(node.name, symbol):
                        entry = {'path': rel, 'line': node.lineno, 'kind': 'class' if isinstance(node, ast.ClassDef) else ('async_function' if isinstance(node, ast.AsyncFunctionDef) else 'function'), 'name': node.name}
                        if isinstance(node, ast.ClassDef):
                            entry['bases'] = [short_base(b) for b in node.bases]
                        definitions.append(entry)
                elif isinstance(node, ast.Assign):
                    for target in node.targets:
                        if isinstance(target, ast.Name) and is_match(target.id, symbol):
                            definitions.append({'path': rel, 'line': node.lineno, 'kind': 'assignment', 'name': target.id})
                elif isinstance(node, (ast.AnnAssign, ast.AugAssign)):
                    target = node.target
                    if isinstance(target, ast.Name) and is_match(target.id, symbol):
                        definitions.append({'path': rel, 'line': node.lineno, 'kind': 'assignment', 'name': target.id})
    if include_refs:
        refs_seen = set()
        unique_refs = []
        for item in references:
            key = (item['path'], item['line'])
            if key not in refs_seen:
                refs_seen.add(key)
                unique_refs.append(item)
        references = unique_refs[:max_results]
    definitions = definitions[:max_results]
    lines = []
    lines.append('Searched %d Python files under %s.' % (files_searched, root))
    lines.append('Found %d definition(s) and %d reference(s) for symbol %r.' % (len(definitions), len(references), symbol))
    if definitions:
        lines.append('')
        lines.append('Definitions:')
        for d in definitions:
            extra = ''
            if 'bases' in d:
                extra = ' bases=[%s]' % ', '.join(d['bases'])
            lines.append('  %s:%d %s %s%s' % (d['path'], d['line'], d['kind'], d['name'], extra))
    if references:
        lines.append('')
        lines.append('References:')
        for r in references:
            lines.append('  %s:%d %s' % (r['path'], r['line'], r['text']))
    content = '\n'.join(lines)
    print(json.dumps({'content': content, 'details': {'files_searched': files_searched, 'definitions': definitions[:100], 'references': references[:100]}}))
if __name__ == '__main__':
    main()

